/* History with religion woven in (BACKLOG D6, 18 November 2026): the data model and the pilot of about eighty events (tools/atlas_src/json/world_*.json), the build's guard, the pure logic of the line
   (2z-history-core.js: the scale with no year 0, tick marks, lane placement by priority, the religion strand taken from the Atlas's own events, what else was happening, the address), and the page's
   markup (6pw-history.js) for every event, with hostile data. The words are held to the project's neutrality rule: nothing of accusation or praise in the tool's own voice, and every disputed or
   reported entry says where the sources differ. Needs only the project folder for the data and logic (the built atlas/ and texts/ are checked too when they are there). Run: node tests/history.test.js */
const fs = require('fs'); const path = require('path'); const vm = require('vm'); const { execFileSync } = require('child_process');
const ROOT = path.join(__dirname, '..'); const dir = path.join(ROOT, 'src/js'); const proj = path.join(ROOT, '..'); const J = path.join(ROOT, 'tools/atlas_src/json');
let pass = 0; let fail = 0; const ok = (n, c, x = '') => { if (c) pass++; else { fail++; console.log('FAIL', n, typeof x === 'string' ? x : JSON.stringify(x).slice(0, 400)); } };
const src = (f) => fs.readFileSync(path.join(dir, f), 'utf8'); const strip = (s) => s.replace(/\nif \(typeof module !== 'undefined' && module\.exports\)[^\n]*/g, '');
const rd = (n) => JSON.parse(fs.readFileSync(path.join(J, n + '.json'), 'utf8')); const H = require(path.join(dir, '2z-history-core.js')); const L = require(path.join(dir, '24-data-path-lib.js'));
const wcf = rd('world_conflicts'); const mineIds = new Set(wcf.entries.map((e) => e.id));      /* the conflicts and settlements (D8) are laid over the events of the world, as tools/build_atlas.py does: an entry of the same id replaces the pilot’s, the file stays in date order */
const eventsAll = rd('world_events').filter((e) => !mineIds.has(e.id)).concat(wcf.entries).sort((a, b) => a.year_start - b.year_start || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
const events = eventsAll.filter((e) => e.year_start <= 1900);      /* what the timeline draws: its window ends in 1900, so a conflict after that is on the Conflicts page only (the built file below is compared with eventsAll) */
const strands = rd('world_strands'); const meta = Object.assign({}, rd('world_meta'), { conflicts: wcf.meta }); const trads = new Set(rd('traditions').map((t) => t.id)); const byId = Object.fromEntries(events.map((e) => [e.id, e]));

/* ── the scale: years are signed with no year 0 ── */
const ppy = 0.5;
ok('1 BCE and 1 CE are one year apart on the line, not two, and a year is where its start is', Math.abs(H.histX(1, -3500, ppy) - H.histX(-1, -3500, ppy) - ppy) < 1e-9 && H.histX(-3500, -3500, ppy) === 0 && H.histX(1, -3500, ppy) === 3500 * ppy);
ok('the line runs forward: the x of a later year is larger, over every year of the span', (() => { let prev = -1; for (let y = H.HIST_RANGE.from; y <= H.HIST_RANGE.to; y++) { if (y === 0) continue; const x = H.histX(y, H.HIST_RANGE.from, ppy); if (x <= prev) return false; prev = x; } return true; })());
ok('a pixel gives back its year, never year 0, and the round trip holds for every year at several zooms', [0.04, 0.17, 1, 7.5, 40].every((p) => { for (let y = H.HIST_RANGE.from; y <= H.HIST_RANGE.to; y++) { if (y === 0) continue; if (H.histYearAt(H.histX(y, H.HIST_RANGE.from, p) + p * 0.3, H.HIST_RANGE.from, p) !== y) return false; } return true; }));
ok('the whole span fits the width at zoom 1; a zoom is a multiple of that; the zoom is held between its limits', Math.abs(H.histPpy(900, 1) * (H.histT(1900) - H.histT(-3500)) - 900) < 1e-6 && Math.abs(H.histPpy(900, 4) - 4 * H.histPpy(900, 1)) < 1e-9 && H.histPpy(900, 0.1) === H.histPpy(900, 1) && H.histPpy(900, 1e9) === H.histPpy(900, H.HIST_ZOOM.max) && H.histPpy(10, 1) === H.histPpy(120, 1));
ok('years are named as the Atlas names them (BCE, CE under 1000, plain after) and a range is written the same way', H.histYearLabel(-3500) === '3500 BCE' && H.histYearLabel(79) === '79 CE' && H.histYearLabel(1453) === '1453' && H.histRangeLabel(-539, -516, true) === 'c. 539–516 BCE' && H.histRangeLabel(610, 610, false) === '610 CE' && H.histRangeLabel(750, 1258, false) === '750 CE – 1258' && H.histRangeLabel(-202, 220, false) === '202 BCE – 220 CE' && H.histRangeLabel(1095, 1099, false) === '1095–1099' && H.histRangeLabel(100, 940, true) === 'c. 100–940 CE');
const tk = (p) => H.histTicks(-3500, 1900, p, 70);
ok('tick labels are spaced so none touches the next (at every zoom), are round years, and the year 0 is the 1 CE of the line', [0.05, 0.17, 0.5, 2, 9, 40].every((p) => { const t = tk(p); const xs = t.major.map((m) => H.histX(m.y, -3500, p)); return t.major.length >= 1 && xs.every((x, i) => !i || x - xs[i - 1] >= 69.9) && t.major.every((m) => m.label === H.histYearLabel(m.y) && m.y !== 0); }) && tk(0.17).major.some((m) => m.y === 1 && m.label === '1 CE'));
ok('small marks appear only when there is room for them and never sit on a labelled one', [0.17, 2, 9, 40].every((p) => { const t = tk(p); const maj = new Set(t.major.map((m) => m.y)); return t.minor.every((m) => !maj.has(m.y) && m.label === '') && (t.minor.length === 0 || t.step / 5 * p >= 9); }));
ok('the length of a name is a guess that grows with its text and the order of names to write only grows as the line is zoomed in', H.histLabelMin(0.1) === 5 && H.histLabelMin(0.4) === 4 && H.histLabelMin(0.8) === 3 && H.histLabelMin(2) === 2 && H.histLabelMin(5) === 1 && [0.05, 0.1, 0.3, 0.5, 1, 2, 3, 10].every((p, i, a) => !i || H.histLabelMin(p) <= H.histLabelMin(a[i - 1])));

/* ── placing marks in lanes: the most important first, none touching, a crowded row stays a few lines ── */
const box = (x0, w) => ({ x0, x1: x0 + w });
ok('boxes that touch go to different lanes, boxes that do not share a lane, and no two in a lane come within the gap', (() => { const bs = [box(0, 50), box(30, 50), box(60, 50), box(200, 50), box(210, 20)]; const r = H.histPlace(bs, [5, 5, 5, 5, 5], 6); for (let l = 0; l < r.lanes; l++) { const inl = bs.filter((b, i) => r.lane[i] === l).sort((a, b) => a.x0 - b.x0); for (let i = 1; i < inl.length; i++) if (inl[i].x0 < inl[i - 1].x1 + 6) return false; } return r.lane.every((l) => l >= 0) && r.lane[0] === 0 && r.lane[1] === 1; })());
ok('with a cap on the lanes the most important events win: the least important are left out, and the cap is never broken', (() => { const bs = Array.from({ length: 40 }, (_, i) => box(i * 3, 40)); const pr = bs.map((b, i) => (i === 17 ? 9 : i % 5)); const r = H.histPlace(bs, pr, 6, 3); return r.lanes <= 3 && r.lane[17] === 0 && r.lane.filter((l) => l >= 0).length < 40 && r.lane.filter((l) => l >= 0).length >= 3 && r.lane.every((l) => l >= -1 && l < 3); })());
ok('without a cap every box is placed; an empty row is one lane; the answer does not depend on the order of equal boxes being given', (() => { const bs = Array.from({ length: 30 }, (_, i) => box((i * 37) % 200, 60)); const r = H.histPlace(bs, bs.map(() => 3), 6); const r2 = H.histPlace(bs.slice(), bs.map(() => 3), 6); return r.lane.every((l) => l >= 0) && H.histPlace([], [], 6).lanes === 1 && JSON.stringify(r) === JSON.stringify(r2); })());

/* ── the religion strand is the Atlas's own, chosen by a rule ── */
const AE = [{ k: 'tradition_start', r: 'judaism', t: 'judaism', ys: -539, ye: -516, l: 'Judaism emerges', d: 'c. 539–516 BCE', i: 5, la: 31.78, lo: 35.23, c: 'IL' }, { k: 'tradition_start', t: 'ajivika', ys: -500, ye: -480, l: 'Ājīvika emerges', d: 'c. 500–480 BCE → c. 1300–1400', i: 5 },
  { k: 'tradition_start', t: 'minor', ys: -400, l: 'A small one emerges', d: 'c. 400 BCE', i: 3 }, { k: 'presence', t: 'christianity', ys: 301, l: 'Christianity: adopted by a ruler or state (First state to adopt Christianity.)', d: '301 CE – present', i: 5 }, { k: 'presence', t: 'christianity', ys: 543, ye: 1504, l: 'Christianity: adopted by a ruler or state (Nubian kingdoms.)', d: '543 CE – 1504', i: 5 },
  { k: 'presence', t: 'islam', ys: 700, l: 'Islam: becomes the majority or dominant religion', d: '700 CE – present', i: 5 }, { k: 'tradition_end', t: 'manichaeism', ys: 1500, l: 'Manichaeism ends', d: 'c. 1500', i: 4 }, { k: 'text', t: 'x', ys: 100, l: 'A text', i: 5 }, { k: 'tradition_start', t: 'future', ys: 1950, l: 'Too late emerges', i: 5 }, { k: 'tradition_start', t: 'early', ys: -9000, l: 'Too early emerges', i: 5 },
  { k: 'presence', t: 'christianity', ys: 301, l: 'Christianity: adopted by a ruler or state (First state to adopt Christianity.)', d: '301 CE – present', i: 5 }, { k: 'tradition_start', ys: 200, l: 'No tradition emerges', i: 5 }, null, { k: 'tradition_start', t: 'noyear', l: 'No year emerges', i: 5 }];
const R = H.histReligion(AE);
ok('the rule keeps beginnings of importance 4 or 5, moments a ruler or state took up a tradition (4 or 5) and major endings, and nothing else (no text, no small beginning, nothing outside the span, nothing without a tradition or a year)', R.map((e) => e.label).join('|') === 'Judaism emerges|Ājīvika emerges|Christianity: adopted by a ruler or state|Christianity: adopted by a ruler or state|Manichaeism ends', R.map((e) => e.label));
ok('a beginning is a point with a window of uncertainty, not a duration, and is dated as a window; an adoption keeps the years it lasted', (() => { const j = R.find((e) => e.label === 'Judaism emerges'); const n = R.find((e) => /Nubian|adopted/.test(e.label) && e.year_end === 1504); return j && j.year_end === null && j.window_end === -516 && j.date_label === 'c. 539–516 BCE' && n && n.year_start === 543 && n.window_end === null; })());
ok('the end of a tradition after "c." keeps only its beginning in the date (no "→ c. 1300–1400" after "emerges")', (() => { const a = R.find((e) => e.label === 'Ājīvika emerges'); return a && a.date_label === 'c. 500–480 BCE'; })());
ok('the words in brackets become the detail, a repeated moment is shown once, the ids are unique, and the result is in date order', (() => { const c = R.find((e) => e.detail === 'First state to adopt Christianity'); return c && c.label === 'Christianity: adopted by a ruler or state' && R.filter((e) => e.year_start === 301).length === 1 && new Set(R.map((e) => e.id)).size === R.length && R.every((e, i) => !i || R[i - 1].year_start <= e.year_start); })());
ok('importance is mapped so the line names the beginnings first: a major beginning 5, other beginnings 4, adoptions 3 or 2, endings 2', R.find((e) => e.label === 'Judaism emerges').importance === 5 && R.find((e) => e.label === 'Manichaeism ends').importance === 2 && H.histReligion([{ k: 'tradition_start', t: 'a', ys: 10, l: 'A emerges', i: 4 }])[0].importance === 4 && H.histReligion([{ k: 'presence', t: 'a', ys: 10, l: 'A: adopted by a ruler or state', i: 4 }])[0].importance === 2);
const W0 = { strands: [{ id: 'religion' }, { id: 'states' }], events: [{ id: 'b', strand: 'states', label: 'B', year_start: 100, importance: 3 }, { id: 'a', strand: 'states', label: 'A', year_start: -100, importance: 3 }, { id: 'a', strand: 'states', label: 'dup', year_start: 5, importance: 3 }, { id: 'x', strand: 'nowhere', label: 'X', year_start: 5, importance: 3 }, { id: 'old', strand: 'states', label: 'Old', year_start: -9000, importance: 3 }, { id: 'rel', strand: 'religion', label: 'R', year_start: 5, importance: 3 }, null] };
const M = H.histMerge(W0, AE);
ok('the line is the world’s events and the religious ones together, in date order, each once; an unknown strand, a year outside the span, a repeated id, a damaged row and a religion event typed into the world file are all left out', M.filter((e) => e.strand === 'states').map((e) => e.id).join() === 'a,b' && M.filter((e) => e.strand === 'religion').length === R.length && !M.some((e) => e.id === 'rel' || e.id === 'x' || e.id === 'old') && M.every((e, i) => !i || M[i - 1].year_start <= e.year_start) && new Set(M.map((e) => e.id)).size === M.length);
ok('without a religion strand in the data nothing religious is drawn, and no data at all is an empty line, not an error', H.histMerge({ strands: [{ id: 'states' }], events: [] }, AE).length === 0 && H.histMerge(null, null).length === 0 && H.histMerge({}, undefined).length === 0);

/* ── what else was happening, and the links ── */
const A = [{ id: 'e', strand: 'states', year_start: 100, year_end: 200, importance: 5 }, { id: 's1', strand: 'science', year_start: 120, importance: 4 }, { id: 's2', strand: 'science', year_start: 150, importance: 3 }, { id: 's3', strand: 'science', year_start: 160, importance: 5 }, { id: 'long', strand: 'trade', year_start: -3000, year_end: 1300, importance: 5 }, { id: 'near', strand: 'trade', year_start: 90, importance: 3 },
  { id: 'same', strand: 'states', year_start: 110, importance: 5 }, { id: 'low', strand: 'ideas', year_start: 130, importance: 2 }, { id: 'far', strand: 'ideas', year_start: 900, importance: 5 }, { id: 'rel', strand: 'religion', year_start: 140, importance: 5 }, { id: 'span', strand: 'ideas', year_start: 50, year_end: 300, importance: 4 }];
