ok('the links of an event are found both ways: those it names and those that name it; a link to nothing is dropped', (() => { const b = H.histRelated(LK[1], lby, LK); const a = H.histRelated(LK[0], lby, LK); return b.length === 2 && b.every((r) => r.dir === 'in') && a.length === 1 && a[0].dir === 'out' && a[0].ev.id === 'b' && a[0].note === 'n'; })());
ok('counts for the strand buttons', (() => { const c = H.histCounts([{ strand: 'a' }, { strand: 'a' }, { strand: 'b' }]); return c.a === 2 && c.b === 1 && c.constructor === undefined; })());

/* ── the address: damaged or hostile input is put right ── */
