/* ── the data model and the pilot ── */
const STATUS = ['documented', 'reported', 'disputed']; const CONF = ['H', 'M', 'L', 'C']; const KIND = { primary: 'A', scholarly: 'B', dataset: 'B', reference: 'C' };
