ok('the timeline holds the eighty-six events of the pilot and those added since (about three hundred when finished), from 3500 BCE to 1900 CE, and the data is kept in date order', events.length >= 86 && events.length <= 420 && events.every((e) => e.year_start >= -3500 && e.year_start <= 1900 && e.year_start !== 0 && (e.year_end == null || (e.year_end > e.year_start && e.year_end <= (e.strand === 'conflict' ? 1950 : 1900) && e.year_end !== 0))) && events.every((e, i) => !i || events[i - 1].year_start < e.year_start || (events[i - 1].year_start === e.year_start && events[i - 1].id < e.id)));
