ok('every event has the whole model: an id, a label, a plain date that matches its years, a confidence and a status from the fixed lists, at least one place with coordinates, a summary of one to three sentences, an importance of 1 to 5', events.every((e) => /^[a-z0-9]+(-[a-z0-9]+)*$/.test(e.id) && e.label.length >= 8 && e.date_label === H.histRangeLabel(e.year_start, e.year_end || null, !!e.circa) && CONF.includes(e.date_confidence) && STATUS.includes(e.status) && e.places.length >= 1 && e.places.every((p) => p.name && Math.abs(p.lat) <= 90 && Math.abs(p.lon) <= 180) && e.summary.length >= 80 && e.summary.length <= 520 && (e.summary.match(/[.!?](\s|$)/g) || []).length >= 1 && (e.summary.match(/[.!?](\s|$)/g) || []).length <= 4 && Number.isInteger(e.importance) && e.importance >= 1 && e.importance <= 5), events.filter((e) => e.date_label !== H.histRangeLabel(e.year_start, e.year_end || null, !!e.circa)).map((e) => e.id + ' ' + e.date_label));
ok('ids and labels are unique and the strand of the id’s own event is stated once', new Set(events.map((e) => e.id)).size === events.length && new Set(events.map((e) => e.label)).size === events.length);
ok('every source has a title, a kind and the grade that kind carries (a record from the time A, a scholarly work or database B, a reference summary C), an address only over https, and a reference is an English Wikipedia page named as such (or another reference page on the list of hosts below)', events.every((e) => e.sources.length >= 1 && e.sources.every((s) => s.title && KIND[s.kind] === s.grade && (!s.url || /^https:\/\//.test(s.url)) && (s.kind !== 'reference' || (/^Wikipedia: /.test(s.title) ? /^https:\/\/en\.wikipedia\.org\/wiki\/[^\s]+$/.test(s.url) : HOSTS.test(s.url || ''))) && (s.kind !== 'primary' || !s.url || true))));
ok('no event stands on a reference summary alone where a record or a scholar is named for it in the same entry: the strongest grade of each entry is shown first in no case needed, but an entry that names a record or a work names it as such (grade A or B) with a title', events.filter((e) => e.sources.some((s) => s.grade !== 'C')).every((e) => e.sources.filter((s) => s.grade !== 'C').every((s) => s.title.length > 10)));
